css:
.container-bounds { padding: 8px 4px; }
.bounds-label { font-size: 11px; color: #94a3b8; margin-bottom: 6px; }
.flex-row { display: flex; gap: 8px; width: 310px; border: 2px dashed #f87171; border-radius: 6px; padding: 8px; background: #0d1016; }
.sidebar { flex: 0 0 84px; background: rgba(148, 163, 184, 0.14); border: 1px solid #475569; border-radius: 4px; padding: 8px; font-size: 11px; color: #cbd5e1; }
.main-col { flex: 1 var(--flex-shrink, 1) 0%; min-width: auto; background: rgba(56, 189, 248, 0.12); border: 1px solid #38bdf8; border-radius: 4px; padding: 8px; }
#sandbox-root.min-w-0 .main-col { min-width: 0; border-color: #34d399; background: rgba(52, 211, 153, 0.1); }
.unbreakable { width: var(--content-w, 300px); max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; background: #1e293b; padding: 5px 7px; border-radius: 4px; font-size: 11px; color: #f8fafc; }
#sandbox-root:not(.min-w-0) .unbreakable { max-width: none; }
.readout { margin-top: 14px; font-size: 11px; color: #cbd5e1; background: #0d1016; border: 1px solid #1e293b; border-radius: 4px; padding: 6px 8px; }
